css:
.grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  max-width: 560px;
  padding: 24px;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
}

.box {
  margin: 0;
  padding: 12px;
  border: 1px solid #fdba74;
  border-radius: 8px;
}

.start {
  text-align: start;
}

.center {
  text-align: center;
}

.end {
  text-align: end;
}

.justify {
  text-align: justify;
}
